window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-62a72d6cdb5e7a82"]={"versions": [{"id": "FIG-62a72d6cdb5e7a82", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Lebenszyklus und der Kanalzustände des LIN-Treibers (LIN Driver, Lin) innerhalb der AUTOSAR Classic Platform (Microcontroller Abstraction Layer / MCAL). Das Diagramm unterscheidet Modulebene und Kanalebene (Kanal-Zustandsautomat innerhalb des Modulzustands <code>LIN_INIT</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Modulzustände:</strong></li>\n<li><code>LIN_UNINIT</code>: Uninitialisierter Zustand des Treibers nach dem Reset.</li>\n<li><code>LIN_INIT</code>: Initialisierter Gesamtzustand des Treibers, Träger des verschachtelten Kanalautomaten.</li>\n<li><strong>Kanalzustände (innerhalb von <code>LIN_INIT</code> pro Kanal):</strong></li>\n<li><code>LIN_CH_OPERATIONAL</code>: Betriebsbereiter Zustand für die aktive Busteilnahme.</li>\n<li><code>LIN_CH_SLEEP</code>: Energiesparzustand des Kanals mit aktivierter Wakeup-Erkennung.</li>\n<li><code>LIN_CH_SLEEP_PENDING</code>: Übergangszustand während des Versendens des Go-to-Sleep-Frames.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustand (Reset) auf Modulebene.</li>\n<li>Initialzustand (<code>for each channel</code>) auf Kanalebene.</li>\n<li><strong>API-Funktionen / Trigger:</strong></li>\n<li><code>Lin_Init</code>: Modulinitialisierung.</li>\n<li><code>Lin_GoToSleep</code>: Sendet Sleep-Frame und leitet Schlafenlegen ein.</li>\n<li><code>Lin_GetStatus</code>: Fragt Kanalstatus ab und quittiert Übergang in Sleep.</li>\n<li><code>Lin_GoToSleepInternal</code>: Direktes Schlafenlegen ohne Busbefehl.</li>\n<li><code>Lin_Wakeup</code>: Wecken über Busaktivität / Wakeup-Puls.</li>\n<li><code>Lin_WakeupInternal</code>: Internes Wecken ohne Bussignal.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Modul-Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Eintritt über <code>Reset</code> befindet sich das LIN-Modul im Zustand <code>LIN_UNINIT</code>.</li>\n<li>Der Aufruf von <code>Lin_Init</code> überführt das Modul in den Zustand <code>LIN_INIT</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kanal-Initialisierung & Betriebsphase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Innerhalb von <code>LIN_INIT</code> startet jeder konfigurierte Kanal über den Pseudozustand <code>for each channel</code> direkt im Zustand <code>LIN_CH_OPERATIONAL</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schlafmodi & Übergänge:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>LIN_CH_OPERATIONAL</code> führt der Aufruf von <code>Lin_GoToSleep</code> in den Zustand <code>LIN_CH_SLEEP_PENDING</code>.</li>\n<li>Aus <code>LIN_CH_SLEEP_PENDING</code> wechselt der Kanal über den Aufruf bzw. die Prüfung von <code>Lin_GetStatus</code> in den Zustand <code>LIN_CH_SLEEP</code>.</li>\n<li>Ein direkter Wechsel von <code>LIN_CH_OPERATIONAL</code> nach <code>LIN_CH_SLEEP</code> erfolgt ohne Busrahmen über <code>Lin_GoToSleepInternal</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aufwecken:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>LIN_CH_SLEEP</code> wechselt der Kanal zurück nach <code>LIN_CH_OPERATIONAL</code> entweder über <code>Lin_Wakeup</code> oder über <code>Lin_WakeupInternal</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Modulinitialisierung via <code>Lin_Init</code> ist Voraussetzung für jegliche Kanaloperationen.</li>\n<li>Nach der Initialisierung befindet sich jeder Kanal sofort im Zustand <code>LIN_CH_OPERATIONAL</code>.</li>\n<li>Der Übergang in den Sleep-Modus über <code>Lin_GoToSleep</code> erfordert eine asynchrone Bestätigung / Statusabfrage mittels <code>Lin_GetStatus</code>, bevor die Hardware den stromsparenden Ruhezustand <code>LIN_CH_SLEEP</code> einnimmt.</li>\n<li>Treiber-Implementierungen müssen parallele, unabhängige Zustandsautomaten für jeden physischen LIN-Kanal instanziieren.</li>\n</ul>"}, {"id": "FIG-cd9a365447965593", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Lebenszyklus und der Kanalzustände des LIN-Treibers (LIN Driver, Lin) innerhalb der AUTOSAR Classic Platform (Microcontroller Abstraction Layer / MCAL). Das Diagramm unterscheidet Modulebene und Kanalebene (Kanal-Zustandsautomat innerhalb des Modulzustands <code>LIN_INIT</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Modulzustände:</strong></li>\n<li><code>LIN_UNINIT</code>: Uninitialisierter Zustand des Treibers nach dem Reset.</li>\n<li><code>LIN_INIT</code>: Initialisierter Gesamtzustand des Treibers, Träger des verschachtelten Kanalautomaten.</li>\n<li><strong>Kanalzustände (innerhalb von <code>LIN_INIT</code> pro Kanal):</strong></li>\n<li><code>LIN_CH_OPERATIONAL</code>: Betriebsbereiter Zustand für die aktive Busteilnahme.</li>\n<li><code>LIN_CH_SLEEP</code>: Energiesparzustand des Kanals mit aktivierter Wakeup-Erkennung.</li>\n<li><code>LIN_CH_SLEEP_PENDING</code>: Übergangszustand während des Versendens des Go-to-Sleep-Frames.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustand (Reset) auf Modulebene.</li>\n<li>Initialzustand (<code>for each channel</code>) auf Kanalebene.</li>\n<li><strong>API-Funktionen / Trigger:</strong></li>\n<li><code>Lin_Init</code>: Modulinitialisierung.</li>\n<li><code>Lin_GoToSleep</code>: Sendet Sleep-Frame und leitet Schlafenlegen ein.</li>\n<li><code>Lin_GetStatus</code>: Fragt Kanalstatus ab und quittiert Übergang in Sleep.</li>\n<li><code>Lin_GoToSleepInternal</code>: Direktes Schlafenlegen ohne Busbefehl.</li>\n<li><code>Lin_Wakeup</code>: Wecken über Busaktivität / Wakeup-Puls.</li>\n<li><code>Lin_WakeupInternal</code>: Internes Wecken ohne Bussignal.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Modul-Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Eintritt über <code>Reset</code> befindet sich das LIN-Modul im Zustand <code>LIN_UNINIT</code>.</li>\n<li>Der Aufruf von <code>Lin_Init</code> überführt das Modul in den Zustand <code>LIN_INIT</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kanal-Initialisierung & Betriebsphase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Innerhalb von <code>LIN_INIT</code> startet jeder konfigurierte Kanal über den Pseudozustand <code>for each channel</code> initial im Zustand <code>LIN_CH_SLEEP</code>.</li>\n<li>Der Wechsel aus <code>LIN_CH_SLEEP</code> in den operativen Zustand <code>LIN_CH_OPERATIONAL</code> erfolgt über <code>Lin_Wakeup</code> oder <code>Lin_WakeupInternal</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schlafmodi & Übergänge:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>LIN_CH_OPERATIONAL</code> führt der Aufruf von <code>Lin_GoToSleep</code> in den Zustand <code>LIN_CH_SLEEP_PENDING</code>.</li>\n<li>Aus <code>LIN_CH_SLEEP_PENDING</code> wechselt der Kanal über den Aufruf bzw. die Prüfung von <code>Lin_GetStatus</code> in den Zustand <code>LIN_CH_SLEEP</code>.</li>\n<li>Ein direkter Wechsel von <code>LIN_CH_OPERATIONAL</code> nach <code>LIN_CH_SLEEP</code> erfolgt ohne Busrahmen über <code>Lin_GoToSleepInternal</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Modulinitialisierung via <code>Lin_Init</code> ist Voraussetzung für jegliche Kanaloperationen.</li>\n<li>Nach der Initialisierung befindet sich jeder Kanal standardmäßig im Ruhezustand <code>LIN_CH_SLEEP</code> und muss vor der Teilnahme an der Cluster-Kommunikation explizit geweckt werden (<code>Lin_Wakeup</code> / <code>Lin_WakeupInternal</code>).</li>\n<li>Der Übergang in den Sleep-Modus über <code>Lin_GoToSleep</code> erfordert eine asynchrone Bestätigung / Statusabfrage mittels <code>Lin_GetStatus</code>, bevor die Hardware den stromsparenden Ruhezustand <code>LIN_CH_SLEEP</code> einnimmt.</li>\n<li>Treiber-Implementierungen müssen parallele, unabhängige Zustandsautomaten für jeden physischen LIN-Kanal instanziieren.</li>\n</ul>"}, {"id": "FIG-489b0e01b69d8dfb", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Lebenszyklus und der Kanalzustände des LIN-Treibers (LIN Driver, Lin) innerhalb der AUTOSAR Classic Platform (Microcontroller Abstraction Layer / MCAL). Das Diagramm unterscheidet Modulebene und Kanalebene (Kanal-Zustandsautomat innerhalb des Modulzustands <code>LIN_INIT</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Modulzustände:</strong></li>\n<li><code>LIN_UNINIT</code>: Uninitialisierter Zustand des Treibers nach dem Reset.</li>\n<li><code>LIN_INIT</code>: Initialisierter Gesamtzustand des Treibers, Träger des verschachtelten Kanalautomaten.</li>\n<li><strong>Kanalzustände (innerhalb von <code>LIN_INIT</code> pro Kanal):</strong></li>\n<li><code>LIN_CH_OPERATIONAL</code>: Betriebsbereiter Zustand für die aktive Busteilnahme.</li>\n<li><code>LIN_CH_SLEEP</code>: Energiesparzustand des Kanals mit aktivierter Wakeup-Erkennung.</li>\n<li><code>LIN_CH_SLEEP_PENDING</code>: Nur für LIN-Master (<code>Master only</code>) vorgesehener Übergangszustand während des Versendens des Go-to-Sleep-Frames.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustand (Reset) auf Modulebene.</li>\n<li>Initialzustand (<code>for each channel</code>) auf Kanalebene.</li>\n<li><strong>API-Funktionen / Trigger:</strong></li>\n<li><code>Lin_Init</code>: Modulinitialisierung.</li>\n<li><code>Lin_GoToSleep</code>: Sendet Sleep-Frame und leitet Schlafenlegen ein (<code>Master only</code>).</li>\n<li><code>Lin_GetStatus</code>: Fragt Kanalstatus ab und quittiert Übergang in Sleep (<code>Master only</code>).</li>\n<li><code>Lin_GoToSleepInternal</code>: Direktes Schlafenlegen ohne Busbefehl.</li>\n<li><code>Lin_Wakeup</code>: Wecken über Busaktivität / Wakeup-Puls.</li>\n<li><code>Lin_WakeupInternal</code>: Internes Wecken ohne Bussignal.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Modul-Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Eintritt über <code>Reset</code> befindet sich das LIN-Modul im Zustand <code>LIN_UNINIT</code>.</li>\n<li>Der Aufruf von <code>Lin_Init</code> überführt das Modul in den Zustand <code>LIN_INIT</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kanal-Initialisierung & Betriebsphase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Innerhalb von <code>LIN_INIT</code> startet jeder konfigurierte Kanal über den Pseudozustand <code>for each channel</code> initial im Zustand <code>LIN_CH_SLEEP</code>.</li>\n<li>Der Wechsel aus <code>LIN_CH_SLEEP</code> in den operativen Zustand <code>LIN_CH_OPERATIONAL</code> erfolgt über <code>Lin_Wakeup</code> oder <code>Lin_WakeupInternal</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schlafmodi & Übergänge:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>LIN_CH_OPERATIONAL</code> führt der Aufruf von <code>Lin_GoToSleep</code> in den Zustand <code>LIN_CH_SLEEP_PENDING</code>.</li>\n<li>Aus <code>LIN_CH_SLEEP_PENDING</code> wechselt der Kanal über den Aufruf bzw. die Prüfung von <code>Lin_GetStatus</code> in den Zustand <code>LIN_CH_SLEEP</code>.</li>\n<li>Ein direkter Wechsel von <code>LIN_CH_OPERATIONAL</code> nach <code>LIN_CH_SLEEP</code> erfolgt ohne Busrahmen über <code>Lin_GoToSleepInternal</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Modulinitialisierung via <code>Lin_Init</code> ist Voraussetzung für jegliche Kanaloperationen.</li>\n<li>Nach der Initialisierung befindet sich jeder Kanal standardmäßig im Ruhezustand <code>LIN_CH_SLEEP</code> und muss vor der Teilnahme an der Cluster-Kommunikation explizit geweckt werden (<code>Lin_Wakeup</code> / <code>Lin_WakeupInternal</code>).</li>\n<li>Der zweistufige Einschlafprozess über <code>LIN_CH_SLEEP_PENDING</code> mit den Schnittstellen <code>Lin_GoToSleep</code> und <code>Lin_GetStatus</code> ist explizit als <code>Master only</code> spezifiziert; LIN-Slave-Knoten nutzen diesen Pfad nicht.</li>\n<li>Treiber-Implementierungen müssen parallele, unabhängige Zustandsautomaten für jeden physischen LIN-Kanal instanziieren.</li>\n</ul>"}], "trans": [{"from": "FIG-62a72d6cdb5e7a82", "to": "FIG-cd9a365447965593", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Initialer Zustand pro Kanal geändert: Der Pseudozustand <code>for each channel</code> führt nun nach <code>LIN_CH_SLEEP</code> statt zuvor nach <code>LIN_CH_OPERATIONAL</code>.</li>\n<li>Layout und Anordnung von <code>LIN_CH_SLEEP_PENDING</code> und den Zustandsübergängen umgeordnet: <code>LIN_CH_SLEEP_PENDING</code> liegt nun links oben über <code>LIN_CH_OPERATIONAL</code>, der Übergang via <code>Lin_GoToSleep</code> verläuft senkrecht nach oben und via <code>Lin_GetStatus</code> diagonal nach rechts unten zu <code>LIN_CH_SLEEP</code>.</li>\n</ul>"}, {"from": "FIG-cd9a365447965593", "to": "FIG-489b0e01b69d8dfb", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Umrahmung mit gestrichelter Linie und Kennzeichnung <code>Master only</code> um den Zustand <code>LIN_CH_SLEEP_PENDING</code> sowie die Übergänge <code>Lin_GoToSleep</code> und <code>Lin_GetStatus</code> hinzugefügt; schränkt die Zwischenphase des Einschlafvorgangs auf LIN-Master-Knoten ein.</li>\n</ul>"}]};
